class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def areAnagrams(root1: TreeNode, root2: TreeNode) -> int:
    from collections import deque

    def get_levels(root):
        levels = []
        queue = deque([root])
        while queue:
            level_size = len(queue)
            level = []
            for _ in range(level_size):
                node = queue.popleft()
                level.append(node.val)
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            levels.append(level)
        return levels

    levels1 = get_levels(root1)
    levels2 = get_levels(root2)

    return 1 if all(sorted(level1) == sorted(level2) for level1, level2 in zip(levels1, levels2)) else 0
